#!/usr/bin/env python3
"""Independently reproduce the two provenance tree-digest formats in use."""

from __future__ import annotations

import hashlib
import os
import stat
import sys
from pathlib import Path


def entries(root: Path) -> list[tuple[str, str, Path]]:
    root_stat = os.lstat(root)
    if not stat.S_ISDIR(root_stat.st_mode):
        raise ValueError(f"not a real directory: {root}")
    pending = [root]
    found: list[tuple[str, str, Path]] = []
    while pending:
        directory = pending.pop()
        for item in os.scandir(directory):
            mode = item.stat(follow_symlinks=False).st_mode
            path = Path(item.path)
            relative = path.relative_to(root).as_posix()
            if stat.S_ISDIR(mode):
                kind = "directory"
                pending.append(path)
            elif stat.S_ISREG(mode):
                kind = "file"
            else:
                raise ValueError(f"linked or unsupported tree entry: {path}")
            found.append((relative, kind, path))
    return sorted(found)


def manifest_digest(root: Path) -> str:
    digest = hashlib.sha256()
    for relative, kind, path in entries(root):
        encoded = relative.encode()
        digest.update(len(encoded).to_bytes(4, "big"))
        digest.update(encoded)
        digest.update(kind.encode() + b"\0")
        if kind == "file":
            size = path.stat(follow_symlinks=False).st_size
            digest.update(size.to_bytes(8, "big"))
            with path.open("rb") as stream:
                for chunk in iter(lambda: stream.read(1024 * 1024), b""):
                    digest.update(chunk)
    return digest.hexdigest()


def legacy_digest(root: Path) -> str:
    digest = hashlib.sha256()
    for relative, kind, path in entries(root):
        digest.update(relative.encode() + b"\0" + kind.encode() + b"\0")
        if kind == "file":
            digest.update(path.read_bytes())
    return digest.hexdigest()


for argument in sys.argv[1:]:
    tree = Path(argument)
    print(f"{tree}")
    print(f"  manifest_sha256={manifest_digest(tree)}")
    print(f"  legacy_sha256={legacy_digest(tree)}")

